code.en:
import { defineConfig } from "vite"
import { visualizer } from "rollup-plugin-visualizer"
export default defineConfig({
  define: { __PAYMENTS_V2__: JSON.stringify(false) }, // compile-time, not a secret
  build: {
    sourcemap: "hidden", // emit .map, do not link from JS; upload to Sentry
    rolldownOptions: { // Vite 8. Vite 7 used build.rollupOptions (still mapped)
      output: { codeSplitting: { groups: [{ name: "echarts", test: /node_modules\/echarts/ }] } },
    },
  },
  plugins: [visualizer({ gzipSize: true, emitFile: true })],
})

