code.en:
import { visualizer } from "rollup-plugin-visualizer"
export default defineConfig({
  plugins: [visualizer({ gzipSize: true, brotliSize: true, emitFile: true, filename: "stats.html" })]
  // CI: open stats.html from the same SHA. Sort parsed size.
})
// Only split vendors you know are huge AND not on the first screen.
function manualChunks(id: string) {
  if (id.includes("node_modules/echarts")) return "echarts"
  if (id.includes("monaco-editor")) return "monaco"
}
// Route-level defineAsyncComponent / Nuxt pages should do the rest.

